const titles=TCUI.pageTitles[locale];
title.textContent=titles[page]||(locale==="zh-CN"?"工作台":"Dashboard");const navPage=page==="trade-plan-detail"?"trade-plans":page==="position-detail"?"positions":page==="trade-review-detail"?"trade-reviews":page==="companion-detail"?"companion":page==="market-snapshot-detail"||page==="watchlist-snapshot"||page==="symbol-overview"?"market-snapshots":page.replace("-detail","");document.querySelector(`[data-nav="${navPage}"]`)?.classList.add("active");
