function setBadge(id,label,status){const node=document.querySelector(`#${id}`);if(!node)return;node.textContent=`${label} ${zh[status]||status}`;node.className=`status-pill ${["OK","CONNECTED","RUNNING","ACTIVE"].includes(status)?"good":["DEGRADED","PENDING"].includes(status)?"warn":["FAILED","DISCONNECTED"].includes(status)?"bad":"neutral"}`}
