function tradeReviewTable(items){return table(["标的","类型","结果","MFE / MAE","持有","Target / Stop","复盘时间"],items.map(x=>`<tr><td><a href="/dashboard/trade-reviews/${x.id}"><b>${esc(x.symbol)}</b></a><br><small>${esc(x.timeframe)} / ${esc(x.direction)}</small></td><td>${tag(x.review_type)}</td><td>${tag(x.result)}</td><td>${esc(x.mfe)}% / ${esc(x.mae)}%</td><td>${esc(x.holding_minutes)} min</td><td>${x.target_hit?"命中":"—"} / ${x.stop_hit?"命中":"—"}</td><td>${fmt(x.review_time)}</td></tr>`))}
async function tradeReviews(){const [d,s]=await Promise.all([api("/api/reviews?limit=100"),api("/api/reviews/statistics")]);content.innerHTML=`<div class="card" style="margin-bottom:12px"><b>${locale==="zh-CN"?"交易复盘仅基于已结束对象和历史 K 线进行客观计算，不构成交易建议。":"Trade Reviews objectively calculate completed objects from historical bars and are not trading advice."}</b></div><div class="grid metrics">${metric(locale==="zh-CN"?"系统复盘":"System Reviews",s.system.total_reviews)}${metric(locale==="zh-CN"?"系统成功 / 失败":"System Win / Loss",`${s.system.wins} / ${s.system.losses}`)}${metric(locale==="zh-CN"?"用户已关闭":"User Closed",s.user.closed_positions)}${metric(locale==="zh-CN"?"用户成功 / 失败":"User Win / Loss",`${s.user.wins} / ${s.user.losses}`)}</div>${d.items.length?tradeReviewTable(d.items):empty(locale==="zh-CN"?"暂无复盘记录":"No trade reviews",locale==="zh-CN"?"交易计划结束后，可以生成系统复盘。":"A system review can be generated after a Trade Plan ends.")}`}
async function tradeReviewDetail(){const id=location.pathname.split("/").pop(),d=await api(`/api/reviews/${id}`);content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>本结果使用已有Historical Bars基础计算，不含Tick回放或AI评分。</b></div><div class="grid detail-grid">${metric("标的 / 周期",`${d.symbol} / ${d.timeframe}`)}${metric("类型 / 结果",`${d.review_type} / ${d.result}`)}${metric("Entry / Exit",`${d.entry_price} / ${d.exit_price}`)}${metric("Holding",`${d.holding_minutes} minutes`)}</div><div class="grid split"><section class="card"><h2>Excursion</h2><p>MFE：${esc(d.mfe)}%</p><p>MAE：${esc(d.mae)}%</p><p>Target Hit：${d.target_hit?"是":"否"}</p><p>Stop Hit：${d.stop_hit?"是":"否"}</p></section><section class="card"><h2>Source</h2><p>Trade Plan：<a href="/dashboard/trade-plans/${encodeURIComponent(d.trade_plan_id)}">${esc(d.trade_plan_id)}</a></p><p>User Position：${esc(d.user_position_id??"SYSTEM")}</p><p>Strategy：${esc(d.strategy_name)} ${esc(d.strategy_version)}</p><p>Review Time：${fmt(d.review_time)}</p></section></div>`}
async function companion(){const d=await api("/api/companion-analyses?limit=100");content.innerHTML=`<div class="card" style="margin-bottom:12px"><b>${locale==="zh-CN"?"AI 解释仅说明系统已有数据；策略引擎仍是唯一决策来源。":"AI explanations only interpret saved data; the Strategy Engine remains the sole decision source."}</b></div>${table([locale==="zh-CN"?"标的":"Symbol","Context",locale==="zh-CN"?"关联对象":"Related Object",locale==="zh-CN"?"阶段 / 状态":"Stage / Status",locale==="zh-CN"?"语言":"Language","Provider / Model",locale==="zh-CN"?"状态":"Status",locale==="zh-CN"?"生成时间":"Generated"],d.items.map(x=>`<tr><td><a href="/dashboard/companion/${x.id}"><b>${esc(x.source.symbol??"—")}</b></a></td><td>${tag(x.context_type)}</td><td>${esc(x.trade_plan_id??x.user_position_id??x.trade_review_id)}</td><td>${esc(x.source.lifecycle_stage??"—")}</td><td>${esc(x.language)}</td><td>${esc(x.provider)} / ${esc(x.model)}</td><td>${tag(x.status)}</td><td>${fmt(x.request_completed_at||x.created_at)}</td></tr>`),locale==="zh-CN"?"暂无 AI 分析":"No AI analyses",locale==="zh-CN"?"选择一个交易计划、持仓或复盘后生成分析。":"Generate an analysis from a Trade Plan, position, or review.")}`}
async function companionDetail(){const id=location.pathname.split("/").pop(),d=await api(`/api/companion-analyses/${id}`),x=d.structured_response||{};content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>AI Explanation不参与策略决策，不提供买卖或下单能力。</b></div><div class="grid detail-grid">${metric("标的 / Context",`${d.source.symbol??"—"} / ${d.context_type}`)}${metric("阶段 / 方向",`${d.source.lifecycle_stage??"—"} / ${d.source.direction??"—"}`)}${metric("Provider / Model",`${d.provider} / ${d.model}`)}${metric("状态 / 语言",`${d.status} / ${d.language}`)}</div><section class="card"><h2>AI Summary</h2><p>${esc(x.summary??d.summary??"暂无")}</p><h3>Plan Interpretation</h3><p>${esc(x.plan_interpretation??"暂无")}</p><h3>Lifecycle Guidance</h3><p>${esc(x.lifecycle_guidance??"暂无")}</p><p class="muted">${esc(x.disclaimer??"以上内容不构成投资建议。")}</p></section>${jsonCard("Risk Notes",x.risk_notes||[])}${jsonCard("Positive Factors",x.positive_factors||[])}${jsonCard("Caution Factors",x.caution_factors||[])}${jsonCard("Missing Data Notes",x.missing_data_notes||[])}${jsonCard("Review Interpretation",x.review_interpretation||null)}${jsonCard("Source References",d.source_references)}<section class="card" style="margin-top:14px"><p>Template：${esc(d.template_id)} ${esc(d.template_version)}</p><p>Schema：${esc(d.context_schema_version)} / ${esc(d.response_schema_version)}</p></section>`}
async function portfolios(){const d=await api("/api/portfolios?page_size=100");content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>Portfolio Center只保存用户录入事实，不是券商实时账户。</b></div><div class="grid split"><section>${table(["名称","用户","币种","状态","默认","更新时间"],d.items.map(x=>`<tr><td><a href="/dashboard/portfolios/${x.id}"><b>${esc(x.name)}</b></a></td><td>${esc(x.user_id)}</td><td>${esc(x.currency)}</td><td>${tag(x.status)}</td><td>${x.is_default?"是":"否"}</td><td>${fmt(x.updated_at)}</td></tr>`))}</section><form class="card" id="portfolio-create"><h2>创建 Portfolio</h2><input name="user_id" placeholder="User ID" required><input name="name" placeholder="名称" required><textarea name="description" placeholder="描述"></textarea><select name="currency"><option>USD</option><option>HKD</option><option>CNY</option></select><label><input type="checkbox" name="is_default"> 设为默认</label><button>创建</button></form></div>`;document.querySelector("#portfolio-create").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api("/internal/portfolios",{method:"POST",body:JSON.stringify({user_id:f.get("user_id"),name:f.get("name"),description:f.get("description"),currency:f.get("currency"),is_default:f.has("is_default")})});location.reload()}}
async function portfolioDetail(){const id=location.pathname.split("/").pop(),[p,s,h,w]=await Promise.all([api(`/api/portfolios/${id}`),api(`/api/portfolios/${id}/statistics`),api(`/api/portfolios/${id}/holdings?page_size=200`),api(`/api/portfolios/${id}/watchlist?page_size=200`)]);content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>内部Portfolio记录；不包含券商同步、实时价格或盈亏。</b></div><div class="grid detail-grid">${metric("名称 / 用户",`${p.name} / ${p.user_id}`)}${metric("币种 / 状态",`${p.currency} / ${p.status}`)}${metric("默认",p.is_default?"是":"否")}${metric("创建时间",fmt(p.created_at))}</div><div class="grid metrics">${metric("总持仓",s.total_holdings)}${metric("Open / Closed",`${s.open_holdings} / ${s.closed_holdings}`)}${metric("LONG / SHORT",`${s.long_count} / ${s.short_count}`)}${metric("Watchlist",s.watchlist_count)}</div><section><h2>Holding</h2>${table(["标的","市场","方向","数量","平均成本","状态","开仓"],h.items.map(x=>`<tr><td><a href="/dashboard/holdings/${x.id}">${esc(x.symbol)}</a></td><td>${esc(x.market)}</td><td>${tag(x.direction)}</td><td>${esc(x.quantity)}</td><td>${esc(x.average_cost)}</td><td>${tag(x.status)}</td><td>${fmt(x.opened_at)}</td></tr>`))}</section><div class="grid split"><form class="card" id="holding-create"><h2>记录 Holding</h2><input name="symbol" placeholder="Symbol" required><select name="market"><option>US</option><option>HK</option><option>CN</option></select><select name="direction"><option>LONG</option><option>SHORT</option></select><input name="quantity" placeholder="Quantity" required><input name="average_cost" placeholder="Average Cost" required><textarea name="notes" placeholder="备注"></textarea><button>保存</button></form><form class="card" id="watch-create"><h2>添加 Watchlist</h2><input name="symbol" placeholder="Symbol" required><select name="market"><option>US</option><option>HK</option><option>CN</option></select><textarea name="notes" placeholder="备注"></textarea><button>添加</button></form></div><section><h2>Watchlist <a href="/dashboard/watchlists/${id}/snapshot"><small>查看 Snapshot</small></a></h2>${table(["标的","市场","顺序","备注","操作"],w.items.map(x=>`<tr><td>${esc(x.symbol)}</td><td>${esc(x.market)}</td><td>${x.display_order}</td><td>${esc(x.notes)}</td><td><button onclick="removeWatch(${id},${x.id})" class="danger">删除</button></td></tr>`))}</section>`;document.querySelector("#holding-create").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api(`/internal/portfolios/${id}/holdings`,{method:"POST",body:JSON.stringify({symbol:f.get("symbol"),market:f.get("market"),direction:f.get("direction"),quantity:f.get("quantity"),average_cost:f.get("average_cost"),notes:f.get("notes")})});location.reload()};document.querySelector("#watch-create").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api(`/internal/portfolios/${id}/watchlist`,{method:"POST",body:JSON.stringify({symbol:f.get("symbol"),market:f.get("market"),notes:f.get("notes")})});location.reload()}}
async function holdingDetail(){const id=location.pathname.split("/").pop(),h=await api(`/api/holdings/${id}`),p=await api(`/api/portfolios/${h.portfolio_id}`);content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>Trade Companion 内部 Holding 记录，不是券商实时仓位。</b></div><div class="grid detail-grid">${metric("标的 / 市场",`${h.symbol} / ${h.market}`)}${metric("方向 / 状态",`${h.direction} / ${h.status}`)}${metric("数量 / 平均成本",`${h.quantity} / ${h.average_cost}`)}${metric("Portfolio",p.name)}</div><section class="card"><p>Opened：${fmt(h.opened_at)}</p><p>Closed：${fmt(h.closed_at)}</p><p>Trade Plan：${h.trade_plan_id?`<a href="/dashboard/trade-plans/${h.trade_plan_id}">#${h.trade_plan_id}</a>`:"Not Linked"}</p><p>User Position：${h.user_position_id?`<a href="/dashboard/positions/${h.user_position_id}">#${h.user_position_id}</a>`:"Not Linked"}</p><p>Notes：${esc(h.notes)}</p></section>${h.status==="OPEN"?`<button id="close-holding" class="danger">记录关闭</button>`:""}`;const button=document.querySelector("#close-holding");if(button)button.onclick=async()=>{await api(`/internal/holdings/${id}/close`,{method:"POST",body:"{}"});location.reload()}}
async function removeWatch(portfolioId,id){await api(`/internal/portfolios/${portfolioId}/watchlist/${id}`,{method:"DELETE"});location.reload()}window.removeWatch=removeWatch;
function snapshotTable(items){return table(["Symbol","Latest Price","Candidate","Trade Plan","Holding","Watching","Updated"],items.map(x=>`<tr><td><a href="/dashboard/market-snapshots/${encodeURIComponent(x.symbol)}"><b>${esc(x.symbol)}</b></a><br><small>${esc(x.display_name)}</small></td><td>${esc(x.latest_price??"暂无")}</td><td>${tag(x.candidate_signal)}</td><td>${x.trade_plan_id?`<a href="/dashboard/trade-plans/${encodeURIComponent(x.trade_plan_id)}">${tag(x.trade_plan_status)}</a>`:tag("NONE")}</td><td>${x.holding_id?`<a href="/dashboard/holdings/${x.holding_id}">${tag(x.holding)}</a>`:tag(x.holding)}</td><td>${tag(x.watching)}</td><td>${fmt(x.updated_at)}</td></tr>`))}
async function marketSnapshots(){content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>Market Snapshot只聚合已有数据库事实，不含AI、预测、Broker仓位或实时盈亏。</b></div><div class="filters"><input id="ms-symbol" placeholder="Symbol"><select id="ms-market"><option value="">全部市场</option><option>US</option><option>HK</option><option>CN</option></select><select id="ms-holding"><option value="">全部持仓</option><option value="true">Holding</option><option value="false">Not Holding</option></select><button id="ms-filter">筛选</button></div><div id="snapshot-list"></div>`;async function load(){const q=new URLSearchParams({page:"1",page_size:"100"});if(msSymbol.value)q.set("symbol",msSymbol.value);if(msMarket.value)q.set("market",msMarket.value);if(msHolding.value)q.set("holding",msHolding.value);const d=await api("/api/market-snapshots?"+q);document.querySelector("#snapshot-list").innerHTML=snapshotTable(d.items)}const msSymbol=document.querySelector("#ms-symbol"),msMarket=document.querySelector("#ms-market"),msHolding=document.querySelector("#ms-holding");document.querySelector("#ms-filter").onclick=load;load()}
async function marketSnapshotDetail(){const symbol=decodeURIComponent(location.pathname.split("/").pop()),x=await api(`/api/market-snapshots/${encodeURIComponent(symbol)}`);content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>只读聚合视图；不触发Strategy、Feature、AI或交易。</b></div><div class="grid detail-grid">${metric("Symbol / Market",`${x.symbol} / ${x.market}`)}${metric("Latest Price",x.latest_price??"暂无")}${metric("Strategy",x.strategy_status)}${metric("Updated",fmt(x.updated_at))}</div><div class="grid split"><section class="card"><h2>Market / Feature</h2><p>Display Name：${esc(x.display_name)}</p><p>Latest Bar：${fmt(x.latest_bar_time)}</p><p>Feature：${tag(x.feature_status)}</p><p>Candidate：${tag(x.candidate_signal)}</p></section><section class="card"><h2>Plan / Portfolio</h2><p>Trade Plan：${x.trade_plan_id?`<a href="/dashboard/trade-plans/${encodeURIComponent(x.trade_plan_id)}">${esc(x.trade_plan_status)}</a>`:"Not Linked"}</p><p>Holding：${x.holding_id?`<a href="/dashboard/holdings/${x.holding_id}">${esc(x.holding)}</a>`:esc(x.holding)}</p><p>Quantity：${esc(x.holding_quantity)}</p><p>Average Cost：${esc(x.average_cost)}</p><p>Watch Status：${tag(x.watching)}</p></section></div>`}
async function watchlistSnapshot(){const id=location.pathname.split("/").slice(-2)[0],d=await api(`/api/watchlists/${id}/snapshots?page_size=200`);content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>Investment Watchlist Snapshot，不读取Strategy Watchlist。</b></div>${snapshotTable(d.items)}`}
async function opportunityDetail(){const id=location.pathname.split("/").pop(),d=await api(`/api/opportunities/${id}`);content.innerHTML=`<div class="grid detail-grid">${metric("标的 / 周期",`${d.symbol} / ${d.timeframe}`)}${metric("方向 / 状态",`${d.direction} / ${d.status}`)}${metric("评分 / 可信度",`${d.score} / ${d.confidence??"—"}`)}${metric("参考价格",d.entry_reference_price)}</div>
<div class="grid split"><section class="card"><h2>基本信息</h2><p>策略：${esc(d.strategy_name)} ${esc(d.strategy_version)}</p><p>发现：${fmt(d.detected_at)}</p><p>有效期：${fmt(d.expiry_at)}</p><p>Telegram：${esc(d.notification_status)}</p><p>状态历史：DETECTED → ${esc(d.status)}</p></section><section class="card"><h2>价格参考</h2><p>进入参考：${esc(d.entry_reference_price)}</p><p>止损参考：${esc(d.stop_reference_price)}</p><p>目标参考：${esc(d.target_reference_price)}</p></section></div>
${jsonCard("Feature Snapshot",d.feature_snapshot)}${jsonCard("Strategy Snapshot",d.strategy_snapshot)}${jsonCard("Decision Snapshot",d.decision_snapshot)}`}
function reviewTable(items){return table(["Opportunity","状态","收益","MFE","MAE","持有","窗口","复盘时间"],items.map(x=>`<tr><td><a href="/dashboard/reviews/${x.id}">${esc(x.symbol)} / ${esc(x.timeframe)}</a></td><td>${tag(x.status)}</td><td>${esc(x.return_percent??"—")}%</td><td>${esc(x.mfe_percent??"—")}%</td><td>${esc(x.mae_percent??"—")}%</td><td>${esc(x.holding_bars)} bars</td><td>${esc(x.review_window)}</td><td>${fmt(x.review_time)}</td></tr>`))}
async function reviews(){content.innerHTML=`<div class="filters"><input id="r-symbol" placeholder="Ticker"><select id="r-status"><option value="">全部状态</option><option>REVIEWED</option><option>REVIEW_FAILED</option></select><button id="r-filter">筛选</button><button id="r-run">运行待复盘任务</button></div><div id="review-list"></div>`;async function load(){const q=new URLSearchParams({limit:"100"});if(rSymbol.value)q.set("symbol",rSymbol.value);if(rStatus.value)q.set("status",rStatus.value);const d=await api("/api/review?"+q);document.querySelector("#review-list").innerHTML=reviewTable(d.items)}const rSymbol=document.querySelector("#r-symbol"),rStatus=document.querySelector("#r-status");document.querySelector("#r-filter").onclick=load;document.querySelector("#r-run").onclick=async()=>{await api("/api/review/run",{method:"POST"});load()};load()}
async function reviewDetail(){const id=location.pathname.split("/").pop(),d=await api(`/api/review/${id}`);content.innerHTML=`<div class="grid detail-grid">${metric("标的 / 周期",`${d.symbol} / ${d.timeframe}`)}${metric("状态",d.status)}${metric("收益 / MFE / MAE",`${d.return_percent??"—"}% / ${d.mfe_percent??"—"}% / ${d.mae_percent??"—"}%`)}${metric("持有",`${d.holding_bars} bars / ${d.holding_minutes} min`)}</div>${jsonCard("Outcome Metrics",d.statistics)}${jsonCard("Price Path",d.price_path)}${jsonCard("Reason",d.reason)}`}
function aiReviewTable(items){return table(["ID","Opportunity / Review","标的","方向","策略 / 周期","收益 / MFE / MAE","分类 / Confidence","Provider / Model","状态","创建时间"],items.map(x=>`<tr><td><a href="/dashboard/ai-reviews/${x.id}">#${x.id}</a></td><td>#${x.opportunity_id} / #${x.opportunity_review_id}</td><td>${esc(x.symbol)}</td><td>${tag(x.direction)}</td><td>${esc(x.strategy)} / ${esc(x.timeframe)}</td><td>${esc(x.review_return??"—")}% / ${esc(x.review_mfe??"—")}% / ${esc(x.review_mae??"—")}%</td><td>${esc(x.outcome_classification??"—")} / ${esc(x.confidence_score??"—")}</td><td>${esc(x.provider)} / ${esc(x.model)}</td><td>${tag(x.status)}${x.is_mock?' <span class="tag warn">TEST / MOCK OUTPUT</span>':""}</td><td>${fmt(x.created_at)}</td></tr>`))}
async function aiReviews(){content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>AI分析仅供研究与复盘，不构成投资建议。</b></div><div class="filters"><input id="a-symbol" placeholder="Ticker"><select id="a-status"><option value="">全部状态</option>${["PENDING","RUNNING","COMPLETED","FAILED","SKIPPED","INSUFFICIENT_DATA"].map(x=>`<option>${x}</option>`)}</select><button id="a-filter">筛选</button><button id="a-run">运行AI分析</button></div><div id="ai-list"></div>`;async function load(){const q=new URLSearchParams({limit:"100"});if(aSymbol.value)q.set("symbol",aSymbol.value);if(aStatus.value)q.set("status",aStatus.value);const d=await api("/api/ai-review?"+q);document.querySelector("#ai-list").innerHTML=aiReviewTable(d.items)}const aSymbol=document.querySelector("#a-symbol"),aStatus=document.querySelector("#a-status");document.querySelector("#a-filter").onclick=load;document.querySelector("#a-run").onclick=async()=>{await api("/api/ai-review/run",{method:"POST",body:JSON.stringify({limit:20})});load()};load()}
async function aiReviewDetail(){const id=location.pathname.split("/").pop(),d=await api(`/api/ai-review/${id}`);content.innerHTML=`<div class="card" style="margin-bottom:14px"><b>AI分析仅供研究与复盘，不构成投资建议。</b>${d.is_mock?' <span class="tag warn">TEST / MOCK OUTPUT</span>':""}</div><div class="grid detail-grid">${metric("标的 / 方向",`${d.symbol} / ${d.direction}`)}${metric("分类 / Confidence",`${d.outcome_classification??"—"} / ${d.confidence_score??"—"}`)}${metric("Provider / Model",`${d.provider} / ${d.model}`)}${metric("状态",d.status)}</div><section class="card"><h2>AI Summary</h2><p>${esc(d.summary||"暂无")}</p><h3>Outcome Explanation</h3><p>${esc(d.outcome_explanation||"暂无")}</p></section>${jsonCard("Facts",d.facts)}${jsonCard("Positive Factors",d.positive_factors)}${jsonCard("Negative Factors",d.negative_factors)}${jsonCard("Risk Factors",d.risk_factors)}${jsonCard("Timing Analysis",d.timing_analysis)}${jsonCard("Market Regime Analysis",d.market_regime_analysis)}${jsonCard("Historical Comparison",d.historical_comparison)}${jsonCard("Investigation Items",d.investigation_items)}${jsonCard("Uncertainty",d.uncertainty_notes)}${jsonCard("Input Snapshot",d.input_snapshot)}${jsonCard("Runtime Metadata",d.runtime)}${jsonCard("Error Information",d.error)}`}
function jsonCard(name,data){return `<details class="card" style="margin-top:14px" open><summary><b>${name}</b></summary><pre class="json">${esc(JSON.stringify(data,null,2))}</pre></details>`}
async function runtime(){const d=await api("/api/runtime/status");content.innerHTML=`<div class="actions"><button id="start">启动 Runtime</button><button id="stop" class="danger">停止 Runtime</button><button id="refresh" class="ghost">刷新状态</button></div><div id="runtime-result" style="margin:14px 0"></div><div class="grid metrics">${metric("Runtime",d.runtime.status)}${metric("OpenD",d.runtime.opend_connected?"已连接":"未连接")}${metric("Runtime PID",d.runtime.pid||"未运行")}${metric("最后策略",fmt(d.runtime.last_strategy_run_at))}</div><section class="card"><h2>服务明细</h2>${d.services.map(service).join("")||empty("暂无服务状态")}</section>`;document.querySelector("#start").onclick=()=>control("start");document.querySelector("#stop").onclick=()=>control("stop");document.querySelector("#refresh").onclick=()=>location.reload()}
async function system(){const v=await api("/api/platform/version");content.innerHTML=`<section class="card symbol-header"><div class="card-header"><div><p class="eyebrow">PRODUCT VERSION</p><h2>${esc(v.product)}</h2><p class="muted">${locale==="zh-CN"?"正式版本与发布信息中心":"Product version and release information"}</p></div><img src="/dashboard/static/branding/trade-companion-logo.png" alt="Trade Companion Logo" width="64" height="64" style="border-radius:12px;object-fit:contain"></div></section><div class="grid metrics">${metric(locale==="zh-CN"?"版本":"Version",v.version)}${metric("Sprint",v.sprint)}${metric("Build",fmt(v.build_time))}${metric("Git Commit",v.commit)}${metric("Alembic",v.migration)}${metric(locale==="zh-CN"?"Git 分支":"Git Branch",v.git_branch)}</div><section class="card"><div class="card-header"><h2>${locale==="zh-CN"?"发布说明":"Release Notes"}</h2><span class="tag info">BETA.1</span></div><p>${locale==="zh-CN"?"Beta 版本用于 Windows 长期运行观察；仅支持系统模拟交易，不提供真实券商下单。":"This Beta is for Windows operational observation; it supports system paper trading only and never submits real broker orders."}</p><a class="button secondary" href="/dashboard/reports">${locale==="zh-CN"?"查看历史报告":"View Reports"}</a></section>`}
async function research(){const d=await api("/api/research");content.innerHTML=`<div class="filters"><input id="research-symbol" placeholder="Ticker"><button id="research-filter">筛选</button></div><div id="research-list">${researchTable(d.items)}</div>`;document.querySelector("#research-filter").onclick=async()=>{const symbol=document.querySelector("#research-symbol").value,q=symbol?`?symbol=${encodeURIComponent(symbol)}`:"",x=await api("/api/research"+q);document.querySelector("#research-list").innerHTML=researchTable(x.items)}}
function researchTable(items){return table(["Workspace","标的","周期","策略","状态","更新时间"],items.map(x=>`<tr><td><a href="/dashboard/research/${x.id}">#${x.id}</a></td><td>${esc(x.symbol)}</td><td>${esc(x.timeframe)}</td><td>${esc(x.strategy_name)}</td><td>${tag(x.status)}</td><td>${fmt(x.updated_at)}</td></tr>`))}
async function researchDetail(){const id=location.pathname.split("/").pop(),d=await api(`/api/research/${id}`);content.innerHTML=`<div class="grid detail-grid">${metric("Workspace",`#${d.workspace.id}`)}${metric("标的 / 周期",`${d.workspace.symbol} / ${d.workspace.timeframe}`)}${metric("Opportunity",`#${d.opportunity.id}`)}${metric("状态",d.workspace.status)}</div><div class="grid split"><section class="card"><h2>Timeline</h2>${d.timeline.map(x=>`<p><small>${fmt(x.event_time)}</small><br><b>${esc(x.title)}</b> ${tag(x.event_type)}</p>`).join("")||"暂无事件"}</section><section class="card"><h2>Manual Note</h2><form id="research-note"><select name="note_type"><option>OBSERVATION</option><option>HYPOTHESIS</option><option>VALIDATION</option><option>EXPERIENCE</option><option>NEXT_STEP</option></select><textarea name="content" required placeholder="观察、猜想、验证、经验或后续计划"></textarea><button>保存笔记</button></form>${d.notes.map(x=>`<p>${tag(x.note_type)} ${esc(x.content)}</p>`).join("")||"暂无笔记"}</section></div>${jsonCard("Evidence",d.evidence)}${jsonCard("Investigation Board",d.investigations)}${jsonCard("Attachments",d.attachments)}${jsonCard("Opportunity",d.opportunity)}${jsonCard("Review",d.review)}${jsonCard("AI Review",d.ai_reviews)}<section class="card" style="margin-top:14px"><button id="similarity">Find Similar Review</button><div id="similarity-result"></div></section>`;document.querySelector("#research-note").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api(`/api/research/${id}/notes`,{method:"POST",body:JSON.stringify({content:f.get("content"),note_type:f.get("note_type"),created_by:"DASHBOARD_ADMIN"})});location.reload()};document.querySelector("#similarity").onclick=async()=>{const x=await api(`/api/research/${id}/similarity`);document.querySelector("#similarity-result").innerHTML=jsonCard("相似案例",x.items)}}
async function control(action){try{const d=await api(`/api/runtime/${action}`,{method:"POST"});document.querySelector("#runtime-result").innerHTML=`<p class="tag good">${esc(d.status_text||d.status)}</p>`}catch(e){document.querySelector("#runtime-result").innerHTML=`<p class="tag bad">${esc(e.message)}</p>`}}
async function strategies(detail=false){const d=await api("/api/dashboard/strategy-summary"),name=detail?decodeURIComponent(location.pathname.split("/").pop()):null,items=name?d.items.filter(x=>x.strategy_name===name):d.items;if(!items.length){content.innerHTML=empty("暂无足够策略数据");return}content.innerHTML=items.map(s=>`<section class="card" style="margin-bottom:14px"><h2><a href="/dashboard/strategies/${encodeURIComponent(s.strategy_name)}">${esc(s.strategy_name)}</a> <span class="tag">${esc(s.strategy_version)}</span></h2><div class="grid metrics">${metric("Signal",s.signal_total)}${metric("Opportunity",s.opportunity_count)}${metric("平均评分",s.average_score)}${metric("最近运行",fmt(s.latest_run_at))}</div><p>周期：${s.supported_timeframes.map(tag).join(" ")||"暂无"}</p><p>适用模板：${s.symbol_templates.map(tag).join(" ")||"暂无"}</p>${jsonCard("Signal分布",s.signal_counts)}${jsonCard("评分分布",s.score_distribution)}${jsonCard("最近失败Gate",s.failed_gates)}</section>`).join("")}
async function quality(){const d=await api("/api/dashboard/data-quality");content.innerHTML=`<div class="grid metrics">${metric("数据库",d.database_size_text)}${metric("最大核心表",d.largest_core_table)}${metric("最近导入",fmt(d.latest_import_at))}${metric("导入错误",d.latest_import_error||"无")}</div>${table(["标的","周期","K线数","最早 / 最新","问题","Feature","Strategy"],d.items.map(x=>`<tr><td>${esc(x.symbol)}</td><td>${x.timeframes.map(t=>tag(t.timeframe)).join(" ")||"无"}</td><td>${Number(x.bar_count).toLocaleString()}</td><td>${fmt(x.timeframes[0]?.earliest)}<br>${fmt(x.latest_data_at)}</td><td>${x.gap_or_issue_count}</td><td>${x.feature_calculable?tag("可计算"):tag("数据不足")}</td><td>${tag(x.strategy_data_status)}</td></tr>`))}`}
async function reports(){const d=await api("/api/dashboard/summary");content.innerHTML=`<div class="grid report-cards">${["日报","周报","月报"].map((x,i)=>`<section class="card"><p class="eyebrow">${i?"PLACEHOLDER":"CURRENT"}</p><h2>${x}</h2><p class="muted">${i?"数据结构已预留，后续Sprint实现。":`今日机会 ${d.today.opportunities} · 异常 ${d.today.errors} · Telegram推送 ${d.today.status_counts.NOTIFIED||0}`}</p></section>`).join("")}</div>`}
async function development(){const d=await api("/api/development/issues");content.innerHTML=`<div class="grid split"><section><div class="filters"><select id="i-status"><option value="">全部状态</option>${["INBOX","INVESTIGATING","WAITING_APPROVAL","APPROVED","IN_DEVELOPMENT","REVIEW","COMPLETED","REJECTED"].map(x=>`<option>${x}</option>`)}</select><button id="i-filter">筛选</button></div><div id="issues">${issueTable(d.items)}</div></section><form class="card" id="issue-form"><h2>创建 Issue</h2><input name="title" placeholder="标题" required><textarea name="description" placeholder="问题描述" required></textarea><select name="priority"><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option><option>LOW</option></select><button>创建</button></form></div>`;document.querySelector("#i-filter").onclick=async()=>{const status=document.querySelector("#i-status").value,x=await api("/api/development/issues"+(status?`?status=${status}`:""));document.querySelector("#issues").innerHTML=issueTable(x.items)};document.querySelector("#issue-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api("/api/development/issues",{method:"POST",body:JSON.stringify({title:f.get("title"),description:f.get("description"),priority:f.get("priority"),source_type:"ADMIN",category:"GENERAL"})});location.reload()}}
function issueTable(items){return table(["ID","标题","来源","优先级","状态","创建时间"],items.map(x=>`<tr><td><a href="/dashboard/development/${x.id}">#${x.id}</a></td><td><b>${esc(x.title)}</b><br><small class="muted">${esc(x.description)}</small></td><td>${esc(x.source_type)}</td><td>${tag(x.priority)}</td><td><select onchange="updateIssue(${x.id},this.value)">${["INBOX","INVESTIGATING","EVIDENCE_READY","WAITING_APPROVAL","APPROVED","CODEX_PROMPT_READY","IN_DEVELOPMENT","REVIEW","COMPLETED","REJECTED"].map(s=>`<option ${s===x.status?"selected":""}>${s}</option>`)}</select></td><td>${fmt(x.created_at)}</td></tr>`))}
async function developmentDetail(){const id=location.pathname.split("/").pop(),x=await api(`/api/development/issues/${id}`);content.innerHTML=`<div class="grid detail-grid">${metric("Issue",`#${x.id}`)}${metric("状态",x.status)}${metric("来源",x.source_type)}${metric("优先级",x.priority)}</div><section class="card"><h2>${esc(x.title)}</h2><p>${esc(x.description)}</p><p class="muted">分类：${esc(x.category)} · 创建：${fmt(x.created_at)} · 更新：${fmt(x.updated_at)}</p></section>${jsonCard("证据",x.evidence_json)}${jsonCard("AI建议（预留）",x.ai_recommendation)}${jsonCard("Codex Prompt（预留）",x.codex_prompt)}`}
async function updateIssue(id,status){await api(`/api/development/issues/${id}`,{method:"PATCH",body:JSON.stringify({status})})}window.updateIssue=updateIssue;
function relatedObjects(x){const labels={snapshot:"Snapshot",trade_plan:"Trade Plan",holding:"Holding",review:"Review",ai:"AI Analysis"};return `<section class="card related-objects"><h2>Related Objects</h2><div class="actions">${Object.entries(labels).map(([k,label])=>x[k]?.available?`<a class="button" href="${esc(x[k].url)}">${label}</a>`:k==="ai"&&x[k]?.can_generate?`<button data-ai-entry="${esc(x[k].action_url)}">View AI Analysis</button>`:`<span class="button disabled">${label} · Not Available</span>`).join("")}</div></section>`}
function symbolHeader(x){const s=x.snapshot;return `<section class="card symbol-header"><p class="eyebrow">SYMBOL WORKSPACE</p><h2><a href="/dashboard/symbols/${encodeURIComponent(x.symbol)}">${esc(x.symbol)}</a></h2><p>${esc(x.market)} · Updated ${fmt(s.updated_at)} · Holding ${s.holding==="HOLDING"?"YES":"NO"}</p></section>`}
async function symbolOverview(){const symbol=decodeURIComponent(location.pathname.split("/").pop()),x=await api(`/api/symbols/${encodeURIComponent(symbol)}/overview`),s=x.snapshot;content.innerHTML=symbolHeader(x)+relatedObjects(x)+`<div class="grid detail-grid">${metric("Latest Price",s.latest_price??"暂无")}${metric("Candidate",s.candidate_signal)}${metric("Trade Plan",s.trade_plan_status)}${metric("Feature",s.feature_status)}</div><div class="grid split"><section class="card"><h2>Snapshot</h2><p>Strategy：${tag(s.strategy_status)}</p><p>Watching：${tag(s.watching)}</p><p>Latest Bar：${fmt(s.latest_bar_time)}</p></section><section class="card"><h2>Current Objects</h2><p>Holding：${x.holding?`${esc(x.holding.quantity)} @ ${esc(x.holding.average_cost)}`:"No Holding"}</p><p>Trade Plan：${x.trade_plan?esc(x.trade_plan.lifecycle_stage):"No Trade Plan"}</p><p>Review：${x.review?esc(x.review.result):"No Review"}</p><p>AI Analysis：${x.ai_analysis?esc(x.ai_analysis.status):"No AI Analysis"}</p></section></div>${x.ai_history.length?jsonCard("AI History",x.ai_history):empty("No AI Analysis History")}`}
async function bindAIEntry(){const button=document.querySelector("[data-ai-entry]");if(!button)return;button.onclick=async()=>{button.disabled=true;try{const result=await api(button.dataset.aiEntry,{method:"POST",body:JSON.stringify({dry_run:false})});if(result.analysis?.id)location.href=`/dashboard/companion/${result.analysis.id}`;else location.reload()}catch(e){button.disabled=false;alert(e.message)}}}
async function telegramPreview(){content.innerHTML=`<div class="card" style="margin-bottom:12px"><b>${locale==="zh-CN"?"Preview Mode：只展示最终消息，不连接、不发送 Telegram。":"Preview Mode: renders the final message without connecting to or sending through Telegram."}</b></div><div class="telegram-preview-layout"><section class="card"><h2>${locale==="zh-CN"?"预览配置":"Preview Settings"}</h2><div class="grid"><label for="tg-symbol">Symbol</label><input id="tg-symbol" value="SOXL" placeholder="SOXL"><label for="tg-language">${locale==="zh-CN"?"消息语言":"Message language"}</label><select id="tg-language"><option value="zh-CN">中文</option><option value="en-US">English</option></select><label for="tg-template">${locale==="zh-CN"?"模板类型":"Template type"}</label><select id="tg-template" disabled title="${locale==="zh-CN"?"当前版本仅支持股票概览":"Only Symbol Overview is available in this release"}"><option>${locale==="zh-CN"?"股票概览":"Symbol Overview"}</option></select><button id="tg-preview">${locale==="zh-CN"?"生成预览":"Generate Preview"}</button></div><p class="fine">${locale==="zh-CN"?"不会读取 Bot Token，也不会进行真实发送。":"No Bot token is read and no message is sent."}</p></section><section id="tg-result" class="telegram-phone">${empty(locale==="zh-CN"?"等待生成预览":"Waiting for preview",locale==="zh-CN"?"输入数据库中已有的 Symbol 查看最终消息。":"Enter a Symbol available in the database to render the final message.")}</section></div>`;document.querySelector("#tg-preview").onclick=async()=>{const symbol=document.querySelector("#tg-symbol").value.trim(),language=document.querySelector("#tg-language").value;if(!symbol)return;try{const x=await api(`/api/telegram-preview/${encodeURIComponent(symbol)}?language=${encodeURIComponent(language)}`);document.querySelector("#tg-result").innerHTML=`<div class="telegram-bubble">${esc(x.message)}</div><p>${tag("PREVIEW")} Sent: ${x.sent?"YES":"NO"}</p><div class="actions">${x.buttons.map(b=>b.enabled?`<span class="button secondary">${esc(b.label)}</span>`:`<span class="button disabled" title="${locale==="zh-CN"?"关联对象不存在":"Related object is unavailable"}">${esc(b.label)} · ${locale==="zh-CN"?"不可用":"Disabled"}</span>`).join("")}</div>`}catch(e){document.querySelector("#tg-result").innerHTML=empty(locale==="zh-CN"?"预览失败":"Preview failed",e.message)}}}
async function unifiedExperience(){if(page==="symbol-overview"){await bindAIEntry();return}const resolvers={"market-snapshot-detail":async()=>decodeURIComponent(location.pathname.split("/").pop()),"trade-plan-detail":async()=>(await api(`/api/trade-plans/${location.pathname.split("/").pop()}`)).symbol,"holding-detail":async()=>(await api(`/api/holdings/${location.pathname.split("/").pop()}`)).symbol,"trade-review-detail":async()=>(await api(`/api/reviews/${location.pathname.split("/").pop()}`)).symbol,"companion-detail":async()=>(await api(`/api/companion-analyses/${location.pathname.split("/").pop()}`)).source.symbol};if(!resolvers[page])return;const symbol=await resolvers[page]();if(!symbol)return;const x=await api(`/api/symbols/${encodeURIComponent(symbol)}/overview`);content.insertAdjacentHTML("afterbegin",symbolHeader(x)+relatedObjects(x));if(page==="companion-detail")content.insertAdjacentHTML("beforeend",jsonCard("Generated From / History",{generated_from:x.ai_analysis?.context_type??"Unavailable",history:x.ai_history}));await bindAIEntry()}
async function marketMonitor(){const d=await api("/api/market-snapshots?page_size=100"),items=d.items||[],admin=items.filter(x=>x.watching==="WATCHING");content.innerHTML=`<section class="card" style="margin-bottom:12px"><div class="card-header"><div><h2>${locale==="zh-CN"?"管理员关注列表":"Administrator Watchlist"}</h2><p class="muted">${locale==="zh-CN"?"管理员每日核心监控列表，始终优先展示。":"The administrator's daily monitoring list is always shown first."}</p></div><span class="tag info">${admin.length}</span></div>${monitorTable(admin)}</section><section class="card"><div class="card-header"><div><h2>${locale==="zh-CN"?"用户关注汇总":"User Watchlist Summary"}</h2><p class="muted">${locale==="zh-CN"?"默认按股票聚合，不展开用户身份。":"Aggregated by symbol; individual users stay collapsed by default."}</p></div></div>${empty(locale==="zh-CN"?"暂无可用用户汇总":"No user summary available",locale==="zh-CN"?"当前版本没有可靠的多用户行为聚合数据，因此不显示推测值。":"Reliable multi-user aggregation is not available, so no inferred values are shown.")}</section>`}
function monitorTable(items){return table([locale==="zh-CN"?"标的":"Symbol",locale==="zh-CN"?"候选":"Candidate",locale==="zh-CN"?"交易计划":"Trade Plan",locale==="zh-CN"?"持仓":"Holding",locale==="zh-CN"?"复盘":"Review","AI",locale==="zh-CN"?"更新时间":"Updated"],items.map(x=>`<tr><td><a href="/dashboard/symbols/${encodeURIComponent(x.symbol)}"><b>${esc(x.symbol)}</b></a></td><td>${tag(x.candidate_signal)}</td><td>${tag(x.trade_plan_status)}</td><td>${tag(x.holding)}</td><td>—</td><td>—</td><td>${fmt(x.updated_at)}</td></tr>`),locale==="zh-CN"?"管理员关注列表为空":"Administrator Watchlist is empty",locale==="zh-CN"?"在投资组合关注列表中添加标的后，将在这里统一监控。":"Symbols added to an investment watchlist appear here.")}
async function paperPositions(){content.innerHTML=`<section class="card"><h2>${locale==="zh-CN"?"我的持仓":"My Positions"}</h2><p class="muted">${locale==="zh-CN"?"展示系统账户的持仓记录，不读取券商账户或用户真实资产。":"System-account positions only; broker accounts and real user assets are never read."}</p>${empty(locale==="zh-CN"?"持仓运行时尚未接入":"Position runtime is not connected",locale==="zh-CN"?"本阶段只完成信息架构，不创建模拟交易或持仓记录。":"This phase only finalizes information architecture and creates no simulated trades or positions.")}</section>`}
async function strategyScoreboard(){const d=await api("/api/dashboard/strategy-summary"),items=d.items||[];content.innerHTML=`<section class="card"><div class="card-header"><div><h2>${locale==="zh-CN"?"策略成绩榜":"Strategy Scoreboard"}</h2><p class="muted">${locale==="zh-CN"?"仅展示现有统计；无可靠复盘指标时统一显示 —。":"Only existing statistics are shown; unavailable review metrics display —."}</p></div></div>${table([locale==="zh-CN"?"策略":"Strategy",locale==="zh-CN"?"胜率":"Win Rate",locale==="zh-CN"?"平均收益":"Average Return",locale==="zh-CN"?"交易数":"Trade Count","Profit Factor",locale==="zh-CN"?"平均持有":"Average Holding",locale==="zh-CN"?"近期表现":"Recent Performance"],items.map(x=>`<tr><td><a href="/dashboard/strategies/${encodeURIComponent(x.strategy_name)}"><b>${esc(x.strategy_name)}</b></a><br><small>${esc(x.strategy_version)}</small></td><td>—</td><td>—</td><td class="numeric">${esc(x.signal_total)}</td><td>—</td><td>—</td><td>${fmt(x.latest_run_at)}</td></tr>`),locale==="zh-CN"?"暂无策略统计":"No strategy statistics",locale==="zh-CN"?"策略产生可审计结果后将在这里形成成绩视图。":"Auditable strategy results will form the scoreboard here.")}</section>`}
async function productFeedback(){const d=await api("/api/development/issues?source_type=USER_FEEDBACK&limit=200"),items=d.items||[],statuses=[["INBOX",locale==="zh-CN"?"待处理":"Open"],["INVESTIGATING",locale==="zh-CN"?"处理中":"In Progress"],["PLANNED",locale==="zh-CN"?"已规划":"Planned"],["COMPLETED",locale==="zh-CN"?"已发布":"Released"],["REJECTED",locale==="zh-CN"?"已拒绝":"Rejected"]];content.innerHTML=`<div class="filters"><input id="feedback-search" placeholder="${locale==="zh-CN"?"搜索标题或内容":"Search title or content"}"><select id="feedback-status"><option value="">${locale==="zh-CN"?"全部状态":"All statuses"}</option>${statuses.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join("")}</select><button id="feedback-filter">${locale==="zh-CN"?"筛选":"Filter"}</button><button class="secondary" disabled title="${locale==="zh-CN"?"Telegram 反馈入口将在 Windows Runtime 联调后启用":"Telegram feedback will be enabled during Windows Runtime integration"}">${locale==="zh-CN"?"新建反馈":"New Feedback"}</button></div><div id="feedback-list"></div><section class="card" style="margin-top:12px"><h2>${locale==="zh-CN"?"管理员通知规则":"Administrator Notification Rules"}</h2><p>${locale==="zh-CN"?"Bug、高优先级建议和多人重复建议计划通知管理员 Telegram；普通反馈仅进入后台。当前仅完成产品设计，不发送消息。":"Bugs, high-priority ideas, and repeated requests are designed for administrator Telegram notification. Ordinary feedback stays in the Dashboard. This phase sends no messages."}</p></section>`;const render=()=>{const query=document.querySelector("#feedback-search").value.trim().toLowerCase(),status=document.querySelector("#feedback-status").value,filtered=items.filter(x=>(!status||x.status===status)&&(!query||`${x.title} ${x.description}`.toLowerCase().includes(query)));document.querySelector("#feedback-list").innerHTML=feedbackTable(filtered)};document.querySelector("#feedback-filter").onclick=render;render()}
function feedbackTable(items){const zhTypes={BUG:"Bug",FEATURE:"功能建议",STRATEGY:"策略建议",MARKET:"新市场建议",OTHER:"其它建议"},enTypes={BUG:"Bug",FEATURE:"Feature Request",STRATEGY:"Strategy Suggestion",MARKET:"New Market",OTHER:"Other"},types=locale==="zh-CN"?zhTypes:enTypes;return table(locale==="zh-CN"?["类型","用户","Bot / 语言","标的","标题 / 摘要","状态","优先级","创建时间","管理员备注"]:["Type","User","Bot / Language","Symbol","Title / Summary","Status","Priority","Created","Admin Note"],items.map(x=>{const evidence=x.evidence_json||{};return `<tr><td>${esc(types[x.category]||x.category)}</td><td>${esc(x.created_by||x.source_reference||"—")}</td><td>${esc(evidence.bot_alias||"—")} / ${esc(evidence.language||"—")}</td><td>${esc(evidence.symbol||"—")}</td><td><a href="/dashboard/development/${x.id}"><b>${esc(x.title)}</b></a><br><small>${esc(x.description)}</small></td><td>${tag(x.status)}</td><td>${tag(x.priority)}</td><td>${fmt(x.created_at)}</td><td>${esc(evidence.admin_note||"—")}</td></tr>`}),locale==="zh-CN"?"暂无用户反馈":"No user feedback",locale==="zh-CN"?"Telegram 反馈闭环接入后，用户提交将自动进入这里。":"User submissions will appear here after Telegram feedback integration.")}
